# -*- coding: utf-8 -*-
"""**运动不合群式**测谎跟踪（用户 2026-10-03 ✓ 三次方案转向的终点 ✓ 都记在下面 ✗ 免得再走一遍）。

用户给的**确定规律**（2026-10-03 原话，逐条）：
  ① 出现"3 秒后…"那个窗口 ⇒ 数秒后开始（本模块没用它 ✓ 留给触发层 ✓）；
  ② 出现正片 ⇒ 开始实时追踪；**一开始依旧用白色图形展示真目标**；
  ③ **假目标钉死在背景上**（相对静止）+ **相机纯平移**缓速平滑随机移动 +
     **"波浪式滤镜"= 画面几何被扭曲**（像隔着水波看 ✓ 用户后来澄清，**不是亮度噪声** ✓）；
  ④ 真目标**相对假目标群体**运动（非匀速、会随机变向）⇒ 与假目标**重叠再分离后**仍要靠
     **运动方式**辨别出来继续跟踪；
  ⑤ **"还是需要依赖 yolo，无论真假至少把目标定位出来"** ✓（用户 2026-10-03 追加）；
  ⑥ **"只有背景有有色，目标都是透明的，但可以看出类似玻璃的轮廓"** ✓（同一天追加 ✓ 关键 ✗）。

────────────────────────────────────────────────────────────────────────
**五次方案（前四条都作废 ✗ 只有最后一条立住 ✓）**
  1. "减掉全局运动 ⇒ 真目标露出"✗ —— 相位相关对齐 + 帧间差分。实测补偿后残差只从 38 降到
     **17.8**（一半都补不掉 ✗）⇒ 前景遍地亮块 ✗。用户确认病根：**波浪是几何扭曲** ⇒
     **"整幅图对齐"这个前提本身不成立** ✗。
  2. "观测用颜色、预测用运动"✗ —— 找最白块（对亮度免疫 ✓ 白星期实测准到 **0~1.4px** ✓）。
     ⚠ 但它**只覆盖开局**：目标**逐渐透明** ⇒ 白度消失 ⇒ 掩膜只剩零碎噪点 ⇒ 无观测 ✗
     （用户第 ⑥ 条坐实了这点：**透明到只剩"玻璃轮廓"** ✗）。
  3. "全图找最强环（玻璃轮廓）"✗ —— 环形显著性 = 圆周梯度 − 内外侧梯度。实测逐帧跳
     **29~305px** ✗ 完全不连续：**背景纹理里的环比目标强**，把目标淹了 ✗。
  4. "框内外不一致度"✗ —— 猜"玻璃 ⇒ 框内纹理被抹平" ⇒ 比框内 vs 周边环带的梯度/对比度。
     实测所有框都只有 **0.05 / 0.02 / 0.00** ✗ 区分度≈0（开局目标是**实的白星**不是玻璃 ✗）。
  ⇒ **5.（现行）yolo 给候选 + "运动不合群"分辨** ✓✓：
     · **yolo 全程检得到**（实测透明期各帧 **15~18 个 cls0 @ conf 0.98** ✓ 用户第 ⑤ 条成立 ✓）
       —— 但它**分不出真假** ✗（尺寸形状都一样 ✓ 用户自己也说"无论真假" ✓）⇒ **它只负责定位** ✓；
     · **真目标 = "运动不合群"的那个** ✓（用户第 ④ 条 ✓）：假目标群体的位移 = **相机平移**
       （同一份 ✓）⇒ 真目标**相对群体**在动 ⇒ 它的位移**偏离群体中位** ✓；
     · ⭐⭐ **为什么波浪毁不掉它** ✓✓：波浪对**全场一视同仁**（同一场波搅所有框 ✓）⇒
       **减掉"同一拍所有框的中位位移"就抵消了** ✓✓ —— 这跟方案 1 的死因**恰好相反**：
       方案 1 对齐的是**整幅图**（波浪一扭曲就对不上 ✗），这里对齐的是**同拍所有框的中位** ✓。

**决定性实测（`10月1日.mp4` 全片 ✓ 探针一次跑完 ✓）**：
  · **噪声底**（假目标那批的"相对群体偏离"中位）= 只有 **3.3~6.5 px** ✓✓
    —— 相机平移 + **波浪抖动** + 配对误差**全在里面** ⇒ 波浪的贡献被抵消得干干净净 ✓；
  · **信号**（每帧 top1 的偏离）= **8~26 px** ⇒ **信噪比 1.6~5.1** ✓；
  · **校准**（唯一有真值的时刻 ✓）：帧 1 白星真值 `(373,251)` ⇒ 帧 6 判据 top1 = **`(373,250)`**
    ✓✓ 完全吻合（信噪比 **5.12** ✓）；帧 6→12→18 的 top1 轨迹 `(373,250)→(354,269)→(317,263)`
    **连续** ✓；
  · ⚠ 探针里"累积偏离"按**框索引**记 ⇒ 索引每帧会变 ⇒ 后面串位（跳到画面另一侧 ✗）——
    **是实现 bug 不是判据问题** ✓ ⇒ 本模块改成**按位置关联的轻量轨迹表** ✓（见下 ✓）。

**每拍流程**（本模块 ✓）：
  ① **配对**：yolo 的框 ↔ 已有轨迹（用轨迹的**预测位置** ✓ 最近邻 + `pair_gate` ✓ **一对一** ✓）；
  ② **群体中位位移**：所有配上的轨迹的"本拍观测量 − 上一拍观测量"取中位 ✓（**≥ `_MIN_PAIRS` 个才算** ✓）；
  ③ **偏离**：`dev = |该框位移 − 群体中位位移|` ✓；
  ④ **累积**：`score = score × score_decay + dev`（**带衰减 ⇒ 追"持续不合群" ✗ 不追"偶然跳一下"** ✓）；
     另加**白度辅助分**（用户第 ② 条 ✓）：`pick_white` 找到的白块附近的轨迹 `+ white_w × _WHITE_HIT`
     ⇒ **开局几条拍就有明确答案** ✓（透明后白度没了 ⇒ 该分自然归零 ✓ 不干扰 ✓）；
  ⑤ **淘汰**：`_TRACK_LOST` 拍没配上的轨迹删掉 ✓；没配上的框**新建**轨迹（score=0 ✓）；
  ⑥ **选目标**：`score` 最高、且 `hits ≥ min_hits` ⇒ 当选 ✓；**切换有迟滞** ✓
     （新候选要超过当前目标 `+ switch_margin` 才换 ⇒ 不抖 ✗）；
  ⑦ **报告**：位置 = 目标轨迹的位置（带平滑 ✓）；速度 = 轨迹速度 ✓；半径由框尺寸学 ✓
     （之后冻结 ✓）；⚠ 目标轨迹**本拍没配上**时 ⇒ 用"上一拍位置 + 速度"外推照给 ✓
     （用户第 ④ 条要的"重叠再分离后**继续跟踪**" ✓）。

⚠ **本模块不做**：相位相关 ✗ / 帧间差分 ✗ / 全图环检测 ✗ / 框内纹理一致性 ✗（前四条都实测作废 ✓）。
⚠ `pick_white` **保留** ✓ 但**只当"开局辅助证据"** ✗ 不再是唯一观测 ✓。
"""
from __future__ import annotations

import math
import time
from collections import deque
from pathlib import Path

import cv2
import numpy as np

from perception import geom                       # ⭐ 重叠尺**全项目同一处**（见其模块头 ✓）
from perception.lie_controller import LieMouseController

# ---------------- 跟踪参数（前 5 个在界面上可调 ✓ 见 `lie_demo` 第 4 行 ✓）----------------
#: **配对门限**（px ✓）：本拍框与轨迹预测位置超过它就配不上 ✓（相机一帧能走几十 px ⇒ 别太小 ✗）。
_PAIR_GATE = 70.0
#: ⭐⭐⭐ **"复活门限"**（px ✓）：框**第一轮没配上任何轨迹**时，再去接"**睡着的旧轨迹**"（`miss > 0`）
#:   时放宽到本值 ✓（**接得上就保住原 id** ✓ 接不上才新建 ✓）。
#:   ⚠⚠ 为什么非要它 ✗（用户 2026-10-03 ✓ 原话："我们的假目标因为**与真目标重叠、噪声**可能
#:   **没被检出**（少数情况），但是其**是不会凭空消失**的，它的**检出框消失后很短时间内再被
#:   检出**" ✓✓）—— 实测坐实 ✓：`10月1日` 全片**总共建过 36 条轨迹** ✗ 而每帧只有 14~17 个框
#:   （全场假目标约 15 个 ✓）⇒ **多出一倍多** ✓ 而且轨迹表常年停在 **29~31 条**（一半是幽灵 ✗）
#:   ⇒ 根因：**"消失几拍再出现"的框，第一轮配上不 ⇒ 直接新建** ✗ ⇒ **同一个目标被反复当新目标** ✓
#:   ⇒ 用户看到的"id 乱"就是这个 ✓（他说得对 ✓ 它们**不会凭空消失** ✓）。
#:   ⇒ 取 `pair_gate` 的 1.6 倍：消失那几拍它**只能靠"群体中位"外推** ✓（会有累积误差 ✓）
#:     ⇒ 给它一个更宽的门 ✓；⚠ 但**别太宽** ✗（宽到 200px 会把两个不同目标接错 ✓）。
#:   ⚠ 取 **160**（≈ `pair_gate` 的 2.3 倍 ✓）：实测（`10月1日` 全片 ✓ 我把"**新建时离最近那条
#:     睡着轨迹的距离**"整量了一遍 ✓）—— 门限 **110 ⇒ 一个都接不上**（≤110 占 **0%** ✗）；
#:     **200 ⇒ 接上 5 条** ✓；400 ⇒ 接上 7 条 ✓。⚠ 但**别调太大** ✗：那个距离的**中位是 365px**
#:     ⇒ 说明"要新建的框"**绝大多数真的是新出现的**（压根不在附近 ✓）⇒ 为了 5~7 条把门限放到
#:     200+ **不划算** ✗（宽门限会把**两个不同目标接错** ✓ —— 那比多几条轨迹更糟 ✓）。
#:   ⚠ 它是 `pair_gate` 的**倍数**（**跟着门限走** ✓）：门限调小/调大时它**自动同步** ✓
#:     —— ⚠ 不这么做的话，把 `pair_gate` 调成 2px 时复活门限还固定 160 ⇒ **"门限真在把关"
#:     那条自检直接失败** ✓（实测踩到 ✓）：一个"谁都配不上"的极端设定，居然靠**复活**把候选
#:     接回来了 ✗ ⇒ 门限形同虚设 ✓。
_REVIVE_K = 2.3
#: ⭐⭐⭐ **R3：拿去"复活"的框不许是碎片 / 被画面切碎的** ✗✗（用户 2026-10-05 ✓ 原话："**R1+R2+R3**" ✓）——
#:   框面积 < 本值 × `std_area`（标准砖面积 ✓）⇒ **不接** ✓（口径与经典追踪器**同源** ✓：登记表
#:   "**太小的**（边缘被切 / 碎片 ✗）**不登记**" ✓ 见 `lie_registry` 85-87 ✓）。
#:   ⚠ **只卡下界** ✗：上界不敢卡 ✓（融合并集框本来就大 ✓ ⇒ 卡上界会把"融合"整个砍掉 ✓）。
#:   ⚠ 取 **0.55**：半块大的框（实测帧 68 那种 42×99 ✓）面积只有 **0.2 倍** ⇒ 一刀切掉 ✓；
#:     正常抖动（框被吃掉一角 ✓）仍在 **0.7 倍**以上 ⇒ **不误杀** ✓。
_R3_SMALL_K = 0.55
#: **偏离累积的每拍衰减**（0.90 ✓）：追"**持续**不合群" ✗ 不追"偶然跳一下" ✓。
_SCORE_DECAY = 0.90
#: ⭐⭐⭐ **`dev` 打分的滑动窗口**（取最近这么多拍的**中位** ✓ 不是单拍 ✗）——
#:   用户 2026-10-04 ✓ 原话："看起来我们对某些**信号过于敏感**了，或者是**反应过早**了" ✓✓
#:   ⚠ 实测坐实（`10月1日` **帧 19** ✓）：`#17` 冒出**单拍** `dev = 69.7` ✗ ⇒ 分数从 58 飙到
#:     116 ⇒ **立刻把真目标 `#13`（84）挤掉** ✗；⚠ 而**下一拍它就掉回 `dev = 6.7`** ✓
#:     ⇒ **那 69.7 是一次性噪声，不是信号** ✗✗（而光标当时**还在真目标附近** ✓ 用户原话：
#:     "第 19 帧，光标其实**是在真目标区域里的**（说明**跟对了**），而 20 帧**急着回头**了" ✓）。
#:   ⇒ 取 **3** 拍中位：单拍尖峰**一抹就掉** ✓，而"**持续**偏离"照样能被中位保住 ✓。
_DEV_WIN = 3
# ---------------- ⚠ **"不合群的持续性"（`persist`）已整体移除**（用户 2026-10-05 ✓）----------
# 原话："**不需要持续门这种逻辑，整体移除**；**就是检出框是真目标的，也很可能就抖一下**" ✓✓
#   —— 它原来是"最近 20 拍里有几拍真在动"的比例（真目标 ≈1.0 / 假目标 ≈0.1~0.2 ✓），
#     用来：① 给 `score` 加权 ✗ ② 当"认领"的第 ④ 道门 ✗。
# ⇒ **为什么该拆** ✗：这个维度问的是"**你过去 20 拍在不在动**" ✗ —— 而我们要认的是
#   "**这一刻、圆附近、出现了一格不属于任何已知目标的干净框**" ✓✓（真目标可能**刚从
#     遮/丢里回来**、只抖一下就被认 ✓）；用"历史比例"当门 ⇒ 恰恰把这种**正当的回归**挡掉 ✗✗
#     （实测 `10月3日 (2)` 帧 45/46：那条 `persist` 只有 **0.40** ✗ ⇒ 被 0.6 挡住 ⇒ 认不上 ✓）。
# ⇒ 现在改用**几何**判据（用户 2026-10-05 的口径 ✓ 见 `_forced_claim` ✓ / `_CLAIM_UNREC_IOU` ✓）：
#   **新框与"已记录目标的模拟框"的 IoU 低** ⇒ 才算"未被记录" ✓ ⇒ 才有资格当那个真目标 ✓。
#: **噪声底的下限**（防"噪声底算出 0 ⇒ 门槛变 0 ⇒ 什么都被算成'在动'"✗）。⚠ 仍在用 ✓
#:   （`dev` 的归一、框心指导、`motion_viz` 的"更不合群"都靠它 ✓）。
_MIN_NOISE = 1.0
# ---------------- ⭐⭐⭐⭐⭐ **「滑行 · 认领」那一档**（用户 2026-10-04 ✓ 他口述的架构 ✓）--------
# 用户原话（三句 ✓ 这是本模块"选谁当目标"的**总纲** ✗ 以后改这里要对着它读 ✓）：
#   ① "**不能在丢了之后立即改认另一个候选**，而是应该：**根据惯性『滑行』**" ✓✓
#   ② "**根据一些『不合群的信号』……修鼠标移动的方向、或是加速 or 减速**" ✓
#   ③ "**直到能以高匹配度认领真目标检出框**" ✓✓
# 他为什么这么要求 ✓（**实测** ✓）：帧 16 目标「粘住 + 冷却 + 连续 2 拍没配上」⇒ 旧逻辑
#   **立刻换人** ⇒ **绿圈瞬移 325px**、鼠标猛冲 200px ✗✗ —— 而那个"换过去的新目标"与
#   "我刚才在哪、往哪走"**毫无关系** ✗（旧判据只看 **谁的 `score` 高** ✓）⇒ 正是他说的
#   "**丢了就立即改认**" ✗。
# ⇒ 新架构 = **三态**（见 `process` ⑥ / ⑦）：
#     · `track`（跟得上 ✓）⇒ **默认不换人** ✗（唯一例外 = 质量自检判它跟丢 ✓）；
#     · `coast`（丢了 ⇒ **滑行** ✓）⇒ **鼠标继续走** ✓（用户 2026-10-04 ✓ "滑行期间鼠标走" ✓）
#       —— 位置 = `上一拍 + 相机位移 + 它自己的相对速度`（与 `pred` **同一个公式** ✓ 一处口径 ✓）；
#     · 滑行期**只接受「认领」** ✓ —— 三条同时满足才接（见 `_claim_candidate` ✓）；
#     · ⚠ **一直滑、不放弃** ✓（用户 2026-10-04 ✓ 原话："**一直滑**" ✓）。
#: **认领的「位置门限」** = `pair_gate × 本值`（滑行越久预测越可能飘 ✗ ⇒ 比配对门限**宽** ✓）。
_CLAIM_GATE_K = 2.0
#: **认领的「不合群门限」** = `本值 × 噪声底`（比"更不合群"的 3 松一点 ✓ —— 这里只要求
#:   "**像个真目标**" ✗ 不是"最像" ✓；⚠ 真正的把关在"位置接得上"那一条 ✓）。
_CLAIM_DEV_K = 2.0
#: ⭐⭐⭐⭐⭐ **"未被记录"的判据**（用户 2026-10-05 ✓ 原话："**即使有编号的假目标检出框消失了，
#:   我们其实也能够模拟出它所在的绝对位置、以及大致的尺寸比例。当新的检出框出现在该假目标记录的
#:   位置附近，算一下新检出框与模拟假目标的 IoU 就能分辨出它是否允许被认为是真目标的检出框**" ✓✓）
#:   —— 新框 ↔ **每一格已记录目标**的"**模拟框**"算 IoU，**全都低于本值** ⇒ 才算"**未被记录**" ✓
#:     ⇒ 才有资格当那个真目标 ✓（⚠ 这条**取代**了原来的"持续性门" ✗ 见上面那段 ✓）。
#:   · **模拟框** = 该轨迹的**预测位置**（`pred` ✓ —— 它漏检在滑行时**照样在外推** ✓ 正是用户
#:     那句"即使检出框消失了也能模拟出它所在的绝对位置" ✓）＋ 它**最后那格的尺寸**（`w,h` ✓
#:     ≈ "大致的尺寸比例" ✓）；
#:   · IoU 用 `perception.geom.iou` ✓（对称、"**是不是同一格**" ✓ 与全项目**同一把尺** ✓ 见其模块头 ✓）；
#:   · ⚠⚠⚠ **门 2026-10-05 从 0.30 抬到 0.55** ✗✗（用户当天报的反例 ✓ 原话："**帧 45/70 …… 无编号：
#:     新出现，或刚被挡住又出来 ｜ NO OWNER。这一拍是应该认领的，查问题**" ✓✓）——
#:     实测（`10月3日 (2)` 帧 46 ✓）**0.30 太低** ✗：那格该被认领的新框（133×147 ✓，圆隙才 **56px**
#:     ✓、`dev = 20.2` ＝ 14 倍噪声底 ✓）被**四条"仅仅挨着"的模拟框**挡住 ✗：
#:       #10 x[88..221] y[76..207] ⇒ IoU **0.44** ｜ #11 x[380..518] ⇒ **0.35** ｜
#:       #12 x[277..436] y[11..121] ⇒ **0.34** ｜ #1 只搭一个角 ⇒ **0.32** ✓
#:     ⇒ 同尺寸的框**相距 50~80px 就能到 0.3~0.44** ✗（而"**就是原来那一格**"该是 **0.7 以上** ✓）
#:     ⇒ 门卡在 0.30 = 画面一挤，**任何新框都被冤杀** ✗✗。
#:   · **门值扫描**（同一段素材 ✓ 看"认完 5 拍还在不在走" ✓）：
#:     0.30 ⇒ 只放出帧 31 ✓（**帧 46 被冤杀** ✗）；**0.45 / 0.55 ⇒ 帧 10 ＋ 帧 31 ＋ 帧 46** ✓
#:     （三笔事后都在走 ✓）；0.70 ⇒ 又放出**帧 24**（认完连 4 拍 `dev = 0` = 砖 ✗）⇒ **取 0.55** ✓。
#:   · ⚠ 要调只动这里 ✓；自检的控制组把它抬到 `1.1`（= 什么都不挡 ✓）✓。
_CLAIM_UNREC_IOU = 0.55
#: ⭐⭐⭐⭐⭐ **"认领"必须认"刚出现/刚回来"的框**（用户 2026-10-05 ✓ 原话："**这一帧将有编号的 #3
