#: ⭐⭐⭐⭐⭐ **进"滑行"时，相对速度怎么"接手"**（用户 2026-10-06 ✓ 他选的**甲** ✓ 原话：
#:   "**我理解的滑行是没有外部作用下 轨迹线是平滑的，不会有任何突兀的转向**" ✓✓）——
#:   ⚠⚠⚠ **实测病根**（`10月1日` 帧 24→25 ✓）：帧 24 还在**挤坐**里（速度走"保住进粘前那份" ✓
#:     ≈ (−1.7, +2.6) ✓），帧 25 **没框了** ⇒ 滑行那条链**把速度整个重算**成"相机 ＋ `vr`" ✗
#:     （= (−48, +14) ✗，一步跳 **20 倍** ✗）⇒ **黄箭头**（= `vel − 相机` ✓）从
#:     (+14.4, −8.6) **整根翻到** (−28.5, +4.3) ✗✗ —— 用户当场问"**为什么 25 帧黄箭头大转向**" ✓。
#:   ⇒ 现在的做法（**甲** ✓）：
#:     · **进滑行那一拍**（`_miss ≤ 1` ✓）⇒ **相对速度 100% 沿用上一拍** ✓（= "接着上一拍走" ✓
#:       上一拍的相对速度 = **上一拍那一步 − 相机** ✓ = 上一拍的黄箭头 ✓）；
#:     · **之后每拍按本值朝"`vr`"靠** ✓（0.30 ⇒ 约 **4~5 拍**过渡完 ✓，全程平滑 ✓）。
#:   ⚠ **为什么作用在"相对"上、而不是"绝对步长"上** ✗✗（**这版才是对的** ✓）：黄箭头读的是
#:     "绝对速度 − 相机" ✓ ⇒ 只把绝对步长接过去 ✗ ⇒ 相机一变、箭头照样翻 ✗ —— 必须让**相对那一份**
#:     接手，位置（= 相机 ＋ 相对 ✓）与箭头才会**同时**平滑 ✓✓。
_COAST_RAMP = 0.30
#: ⚠⚠⚠ **上面这个常数目前"没有接线"** ✗✗（**如实记** ✓）：我按**甲**把它接到了"滑行支"的
#:   `_v` 上 ✓（临时打印证明**执行了** ✓），可 `10月1日` 帧 25 的**黄箭头**与**相对步长**两个读数
#:   **一点没变** ✗ ⇒ 真正决定这两个读数的是**另一条路** ✓（还没定位 ✓）。⇒ 先撤 ✓，
#:   下一步用"**改一处、看读数变不变**"的二分法定位那条路 ✓，再把它接上去 ✓。
#: ⭐⭐⭐⭐⭐ **融合 / 粘连期：四条边给速度的那份增益**（用户 2026-10-06 ✓ 原话："**现在立刻修复，
#:   融合/粘连期在滑行的基础上按四条边分量规则！**" ✓✓）——
#:   规则（= 用户 2026-10-04 那句的字面 ✓："**检出框上边界相对群体向上运动** ⇒ 真目标往哪走" ✓）：
#:     · **基线** = 老办法（粘连期"**保住进粘前的速度**"沿原方向滑 ✓ 用户 2026-10-03 ✓）；
#:     · **在基线之上加一份** = 这条账那格框**四条边的"扩张/收缩"分量** ✓（见 `process` 那段 ✓）：
#:       `(Δ左 − Δ右)/2` 与 `(Δ上 − Δ下)/2` ✓ —— **只取"扩张"那半分** ✗（"整框一起平移"= 中点那份
#:       ✗，那正是用户 10-05 关掉的"框心指导" ✓；**砖是钉在群体里的** ✓ ⇒ "某条边自己在动"
#:       才是**目标自己**往哪走的直接证据 ✓）。
#:   ⚠ 实测（`10月1日` 帧 54~61 ✓）：改前座位 `#8` 的白箭头 **8 拍一格没动** `(−15.5,−2.8)` ✗
#:     （融合期**没有任何东西**把框的几何信息送进圆心速度 ✓）。
#:   ⚠ 增益取 **0.5**：这一份是"边说的相对速度"（px/拍 ✓ 与 `vel` 同系 ✓）⇒ 全量（1.0）太猛
#:     （单拍抖动直接进速度 ✗）；0.5 = 每拍吃掉一半 ⇒ 2~3 拍跟上 ✓（与「夹取增益」同一个思路 ✓）。
_EDGE_GAIN = 1.0
#: ⭐⭐⭐⭐⭐ **"四条边"那份对相对速度的影响 = 转向，不是相加** ✗✗（用户 2026-10-06 ✓ 原话：
#:   "**将四条边的对相对群体速度的影响换成使滑行速度转向该边的相对群体速度方向**" ✓✓ ＋
#:   "**参数用 k = 每拍转向比例 = 「框心力度」**" ✓✓）——
#:   ⚠⚠⚠ **为什么不能再"相加"** ✗✗（**实测** ✓）：`vr ← vr + 边` 是**矢量相加** ⇒
#:     · **反向时会把速度抵掉** ✗（`10月1日` 帧 59：基速 **−15.6** ＋ 边 **+8.6** ⇒ 只剩 **−7.0** ✗）；
#:     · **同向时会放大** ✗（帧 28 一路冲到 **−49.7** ✗）。
#:   ⇒ 改成"**只转方向、不改大小**" ✓（`_edge_turn` ✓）—— 这才对得上"**滑行 = 无外力则匀速**" ✓。
#:   计算（**免算角度** ✓）：`新方向 = normalize((1−r)·v̂ + r·û)` ✓、`新速度 = |v| × 新方向` ✓，
#:   其中 `r = min(0.5, k × w)` ✓，`k` = **「框心力度」**（`fuse_pull` ✓ 界面可调 ✓）、
#:   `w` = 边的**可信度** = `min(1, |边| ÷ (1.5 × 噪声底))` ✓（边太小 ⇒ 不转 ✓ 与"方向投票"同一把尺 ✓）。
#:   ⚠ 兜底：`|边|` 或 `|v|` ≈ 0 ⇒ **原样返回** ✓（不凭空造速度 ✗）。
def _edge_turn(_v, _e, _k, _noise, _conf_k=None):
    #   ⚠⚠ **默认值必须写 `None` 再在函数里取** ✗✗（**这条纪律本项目踩过多次** ✓）：默认参数是在
    #      **定义时**求值的 ✓，而 `_DIR_VOTE_K` 定义在**本函数之后** ⇒ 直接写它会 `NameError` ✗。
    _ck = float(_DIR_VOTE_K) if _conf_k is None else float(_conf_k)
    _en = math.hypot(float(_e[0]), float(_e[1]))
    _vn = math.hypot(float(_v[0]), float(_v[1]))
    if _en <= 1e-9 or _vn <= 1e-9:
        return (float(_v[0]), float(_v[1]))
    _w = min(1.0, _en / max(1e-6, _ck * max(1e-6, float(_noise))))
    _r = max(0.0, min(0.5, float(_k) * _w))
    _ux, _uy = float(_e[0]) / _en, float(_e[1]) / _en
    _vx, _vy = float(_v[0]) / _vn, float(_v[1]) / _vn
    _dx = (1.0 - _r) * _vx + _r * _ux
    _dy = (1.0 - _r) * _vy + _r * _uy
    _dn = math.hypot(_dx, _dy)
    if _dn <= 1e-9:
        return (float(_v[0]), float(_v[1]))
    return (_vn * _dx / _dn, _vn * _dy / _dn)        # **模长原样保留** ✓
#: ⭐⭐⭐⭐⭐ **"四条边"那份并入 KF 速度的比例**（用户 2026-10-06 ✓ 他选的**甲** ✓ 原话：
#:   "**融合/粘连期在滑行的基础上按四条边分量规则！**" ✓✓ ＋ 选"**按比例并入**" ✓）——
#:   ⚠⚠ **为什么必须"按比例"而不是"直接加"** ✗✗（**实测踩到** ✓）：我试过
#:     `kf.x[2] += 边那份` ✗ ⇒ 同一份**每拍又加一次** ⇒ 那是**加速度**不是速度 ✓ ⇒
#:     `vr` 的 y 从 −28 一路涨到 **−43** ✗✗ ⇒ 帧 27 圆心**瞬跳 110px** ✗（**当场撤回** ✓）。
#:   ⇒ 现在：`kf速度 += k × (边那份 − 当前 kf速度)` ✓ ⇒ 只吃**残差** ⇒ **收敛、不自我放大** ✓
#:     （与「夹取增益」同一个思路 ✓ 用户 2026-10-04 那句 ✓）。
#:   ⚠ 取 **0.5**：半量并入 ⇒ 2~3 拍跟到位 ✓、又不会被单拍抖动带飞 ✓。
_EDGE_BLEND = 0.5
#:   ⚠⚠ **2026-10-06 二次订正：0.5 → 1.0** ✗✗（**实测**：用户报"**帧 15 到 24 没看到边相对运动对
#:     圆心速度的影响**" ✓）—— 量下来它**确实在起作用** ✓（`10月1日` 帧 19→22 白箭头 y：
#:     **+8.7 → +7.0 → +1.7 → −0.2** ✓ = 被那几拍的"边 y 全是负（向上）"**一路往上拽** ✓），
#:     但 0.5 的增益每拍只挪 **2~3px** ✗ ⇒ 基线（≈ −29/+5 ✓）一比就**看不见** ✓。
#:   ⇒ 提到 **1.0**（= 边说的相对速度**全量**进这一份 ✓）：它加在"滑行基线"之上 ✓ ⇒ 每拍能挪
#:     **5~9px** ✓ ⇒ 肉眼可见 ✓；⚠ 不更大 ✗（再大就是"让单拍抖动主导速度" ✓ 那正是 10-03 那轮
#:     反面教材 ✓）。
# ---------------- ⭐⭐⭐⭐ **"方向置信度"那一档**（用户 2026-10-04 ✓ 他提的想法 ✓）----------
# 用户原话："是不是置信度可以是**灰箭头的属性**？在**当前鼠标的位置**以**不同角度离散出很多
#   灰色箭头**，**所有在群体坐标系中的几何运动**都会影响**这些方向的置信度**" ✓✓
# 用户还给了**直接证据** ✓（我按他指的正则重测过 ✓）：
#   "**检出框上边界相对群体向上运动**，从 19 帧开始持续到 24 帧……而且明确是**纯递增无负值**" ✓
#   ⇒ 实测（`10月1日` ✓ **追同一个框** ✓）：帧 **20~24** 的上边位移 = **-10.5 / -16.7 / -9.6 /
#     -2.2 / -9.5** ✓（负 = 向上 ✓ 屏幕 y 向下 ✓）⇒ **确实持续为负** ✓✓
#   ⚠ 而这几拍正是我们**跟丢**的时候 ✗ ⇒ **这么明显的信号，我们却在看别的东西** ✓。
# ⇒ 所以加这一层：**"框的四条边"在群体坐标系里每拍挪多少 ⇒ 给对应方向投票** ✓
#   ⚠ 它妙在哪 ✗：① **把"几何运动 → 方向"直接连上** ✓；② **框还没配对时也能算** ✓
#     （弥补"轨迹还没归属"的空档 ✓ 帧 19~24 那个大框就一直"未配对" ✓）；
#     ③ **多框多边投票** ⇒ 天然抗单拍噪声 ✓。
#: **方向数 N**（界面可调 ✓ 用户 2026-10-04 ✓ 原话："**方向数 N 做成配置**" ✓）——
#:   把 360° 等分成 N 格 ✓ 每条边的位移**按角度插值**投进去 ✓（N 越大分得越细 ✓）。
_DIR_N = 16
#: **投票门槛**：一条边的"相对群体位移"要超过**噪声底 × 本值**才投票 ✓（防抖 ✓ 见 `_DEV_WIN`）。
_DIR_VOTE_K = 1.5
#: **切换目标的迟滞余量**（分 ✓）：新候选要超过当前目标这么多分才换 ⇒ 不来回跳 ✓。
_SWITCH_MARGIN = 8.0
