#: ⭐⭐⭐ **框心指导：往「框心方向」加一个分量**（2026-10-04 ✓ 用户最终口径 ✓ 原话：
#:   "把框心指导的**转向**，修改为对圆心的**群体坐标系速度加框心方向的分量（群体坐标系）**" ✓）——
#:   融合期 pos 仍沿原速度滑（老口径 ✓），但在**群体坐标系**里、沿**框心方向**（= 多拍 EMA ✓）
#:   加一个分量，大小 = `_FUSE_PULL ×(框心说的相对速度 − 当前在该方向上的分量)` ✓
#:   （⚠ **由"差"定大小** ⇒ **自限**、不会无端起速 ✗ 见 `_add_along` ✓）。
#:   ⚠⚠ 早先两版都废了 ✗：① "在**绝对**空间里转方向" ⇒ 相机与相对量级相近 ⇒ 把目标的相对运动
#:     抵掉 ✗（实测黄箭头 21px→3.7px ✓）；② 那版的混向公式还是**逐分量相乘** ✗（符号会翻 ✓）。
#:   ⚠⚠ **公式必须"绝对化"** ✗（用户 2026-10-04 追问："vel 方向是什么？" ✓）：`vel` 是**绝对
#:     速度**（含相机 ✓），而"真目标相对群体位移" = `2×(框心−群体)` **不含相机** ✗ ⇒ 直接用会
#:     **差一个相机位移** ⇒ **绝对化** = `2×框心位移 − 群体中位`（**减一次** ✓ 与绝对 vel 同系 ✓）。
#:   几何：融合框心 = 两目标中点（**仅真粘连期** ✓ 见 docs/测谎设计.md §9.1）；单拍噪声被 2×
#:   放大 ⇒ 必须 EMA 平滑后才用方向（大小仍按 vel_decay 衰减 ✓ 不变）。
#:   ⚠ 门控（用户 2026-10-04 ✓）：只在「**sel 自己那格是「真粘连期」（`stuck>0`）且画面里
#:     真粘连框恰好 1 个**」时才拽 ✓（唯一粘连框才能确信含真目标 ✓；多粘连框 / 无粘连 ⇒ 不拽 ✓；
#:     ⚠⚠ **冷却期（`cool>0`）不算** ✗ —— 那时框已分开、框心**不是中点** ⇒ 公式不成立 ✓）。
#:   ⚠⚠ **2026-10-04 订正** ✗：上面那条"**绝对化**"（`2×框心位移 − 群体中位`）**已被实测推翻** ✗✗
#:     —— 绝对速度 = 相机(≈15) ＋ 相对(≈20) **量级相近** ⇒ 在绝对空间里转一点点就把**目标自己的
#:     相对运动**抵掉一大截 ✗（实测帧 17 黄箭头 21px→**3.7px** ✓ 用户当场发现 ✓）。
#:     ⇒ 现在一律用**相对群体**那份 `2×(Δ框心 − 群体中位)` ✓，**并在相对空间里转** ✓
#:     （相机那份最后才加 ✓）⇒ **相对大小一点不动** ✓。详见 `process` 里"框心指导"那段 ✓。
#:   ⚠ `_FUSE_MIN = 3.0`：EMA 模长（= **相对**模长 ✓）低于它不拽（= 这个框基本跟着相机走 ⇒ 不采用 ✓）。
#:   ⭐⭐ **这就是"框心指导的力度"**（用户 2026-10-04 问："我在哪里调控框心指导的力度？" ✓）
#:     —— 现在它**搬到界面上了**：运动分离第 5 行「**框心力度**」✓（`MotionTracker(fuse_pull=…)`
#:     覆盖 ✓ 见 `lie_demo._motion_kw` ✓）。**本常量 = 默认值** ✓（界面别抄一份数 ✗）。
_FUSE_PULL = 0.15
_FUSE_MIN = 3.0
#: ⭐⭐⭐⭐⭐ **"夹取"那份修正算进速度的比例**（用户 2026-10-04 ✓ 原话："**位置被硬夹说明你要么
#:   快了要么慢了，夹取也要算进速度平滑。因为夹取是修正你的预测误差，夹取是较准确的测量值**" ✓✓）。
#:   ⚠ 为什么非有不可 ✗（用户这句话的物理 ✓）：夹取挪了 `d = 夹后 − 夹前` 这一截 ⇒ 等价于说
#:     "**你这一拍本该多走 / 少走 `d`**" ✓ —— 要么快了要么慢了 ✓。而**原来的速度状态一个字不动**
#:     ✗ ⇒ 下一拍照旧按老速度冲 ⇒ **夹取每拍都得再夹一次**（自己跟自己打架 ✓ 实测帧 13~14 每拍
#:     位移 5~15px 全被夹掉 ✓）。
#:   ⇒ 现在把 `d` **记进速度**（"算进速度平滑" ✓）：
#:     · **绝对速度** `vel ← vel + k×d` ✓（`vel` 驱动"粘连期滑行"＋给鼠标前馈 ✓）；
#:     · **KF 的相对速度** `vr` ⇒ 同时写进 `kf.x[2:4]` ✓✗（⚠ **必须写 KF 状态** ✗：`vr` 每拍
#:       都从 `kf.x` 重读 ✓ 只写 `vr` 下一拍就被覆盖 ✓）；
#:     · **相对那份**要减相机（`d − 群体中位` ✓ 与 `vr = vel − 相机` 同一口径 ✓）。
#:   ⚠ **为什么是"比例 k"而不是"一步到位"** ✗（用户原话是"**算进速度平滑**" ✓）：k = 1 ⇒ 把这一截
#:     整根算作速度（判据最信任它 ✓，但一次夹错就整拍带歪 ✗）；k < 1 ⇒ **按几何收敛**（每拍吃掉
#:     `k` 那份残差 ✓ 2~3 拍对齐 ✓ 平滑 ✓）。默认 **0.5** ✓（"较准确"而不是"绝对准确" ✓）。
#:   ⭐⭐ **界面可调**（用户 2026-10-04 ✓ 同"框心力度" ✓）：运动分离那行的「**夹取增益**」✓
#:     （`MotionTracker(clamp_gain=…)` 覆盖 ✓ 见 `lie_demo._motion_kw` ✓）。**本常量 = 默认值** ✓。
_CLAMP_GAIN = 0.0
#:   ⚠⚠⚠ **2026-10-06 按用户要求改默认：0.5 → 0.0（"试试"）** ✗✗（用户原话："**把夹取的速度不算进
#:     速度平滑试试**" ✓✓）—— 即**默认关掉**"把夹取位移算进速度"那一份 ✓（= 老行为：夹取**只挪位置**
#:     ✓、速度状态一个字不动 ✓）。⚠ 界面上的「**夹取增益**」（`clamp_gain` ✓ 见 `lie_demo` ✓）
#:     照旧能把它调回来 ✓（0.5 / 1.0 都还在 ✓）；本行只是**默认值** ✓。
