#:   ⇒ **合方向与 `vr` 的 cos > 本值才拽** ✓；否则这一拍不拽（= 老行为里"没有可信框"那一档 ✓）。
#:   ⚠ 取 `0.0` = "至少得在**同半平面**" ✓。⚠ **每个框心照样都参与**（只是"合方向"没过门时这一拍
#:     不生效 ✓）；想更严就调大 ✓。
_FUSE_AGREE_MIN = 0.0


#: ⭐⭐⭐⭐⭐ **"YOLO 重复检出"的判据**（用户 2026-10-04 ✓ 原话："帧 24 **#27 是凭空生成的**，
#:   它如果存在的话，**早就登记有编号了**，实际这个检出框**是 #1 的一部分（YOLO 重复检出）**" ✓✓）——
#:   若存在**更大**的框 B，使 `交集(A,B) / 面积(A)` ≥ 本值 ⇒ A 判"重复检出" ✓（见 `_dedup` ✓）。
#:   ⚠ 取 `0.90` 的依据（`10月1日` 全片 **1146** 个框实测 ✓）：这种对**一共只有 6 个**
#:     （帧 12 / **23** / **24** / 32 / 60×2 ✓），**全部是 100% 被盖住** ✓（面积比 0.39~0.61 ✓）
#:     ⇒ `0.90` 在本片**零误杀** ✓；而且那些小框的 `conf` 也明显偏低（**0.80** vs 宿主 0.94 ✓）。
#:   ⚠⚠ **不能放更松** ✗（比如 0.5）：目标虽然等大，但**相邻 / 部分重叠**很常见 ⇒ 会误杀真目标 ✓
#:     （自检 `test_dup_detection` ③ 就是钉这条 ✓）。
_DUP_COV = 0.90
#: ⭐⭐⭐⭐⭐ **"跟真目标那格框重叠 ⇒ 这一格先别参与标准群体计算"** 的重叠率门（用户 2026-10-05 ✓
#:   原话："**跟真目标检出框有重叠部分的新检出框暂时不能参与标准群体计算**" ✓✓）——
#:   ⚠ 口径 = **交叠面积 ÷ 较小的那格**（`geom.overlap_min` ✓ 与 `_DUP_COV` 同一把尺 ✓）。
#:   ⚠ 取 **0.30**（不是"碰到就算"✗）：只是"擦个边"的那种框，**框心还是自己的** ✓ ⇒ 拿它当
#:     "大部队怎么走 / 一个目标多大"的样本**没问题** ✓；真正会带歪基准的是**半个框糊在一起**那种 ✓
#:     （那时框心是两人的中点 ✗）。⚠ 想更严/更松 ⇒ 改这一行 ✓（**别在别处另写一个数** ✗）。
#:   ⚠ 打了这个标记的账 = "**次级**"（`_Track.sub` ✓）：有编号 ✓、不当目标 ✗、不进标准参量 ✓；
#:     **重叠一结束就自动晋升回正常** ✓（见 `process` 开头那段 ✓）。
_SUB_COV = 0.30


def _cover(a, b):
    """`a` 被 `b` 盖住的**比例**（交集 ÷ `a` 自己的面积 ✓ 0~1 ✓）—— 纯函数 ✓ 好测 ✓。"""
    _aw, _ah = float(a[3]), float(a[4])
    _x0 = max(float(a[1]) - _aw / 2.0, float(b[1]) - float(b[3]) / 2.0)
    _x1 = min(float(a[1]) + _aw / 2.0, float(b[1]) + float(b[3]) / 2.0)
    _y0 = max(float(a[2]) - _ah / 2.0, float(b[2]) - float(b[4]) / 2.0)
    _y1 = min(float(a[2]) + _ah / 2.0, float(b[2]) + float(b[4]) / 2.0)
    return (max(0.0, _x1 - _x0) * max(0.0, _y1 - _y0)) / max(1.0, _aw * _ah)


#: ⭐⭐⭐⭐⭐ **"宿主必须是同一个物体"那把尺**（用户 2026-10-08 ✓ 第 1 条 ✓ 见 `_dedup` 的
#:   `host_k`）—— 宿主面积 ÷ 小框面积 ≤ 本值 ⇒ 两格**大小差不多** ⇒ 是**同一个物体被吐了两个框**
#:   ⇒ 丢小的 ✓；超过 ⇒ **宿主比它大得多** ⇒ 那是**并集框（两块砖）**⇒ 一个都不许丢 ✓。
#:   ⚠ 取 `1.7` 的依据（`10月7日.mp4` 全片 **430 帧**实测 ✓：**覆盖率 ≥ 0.90 的嵌套框一共只有
#:     `5 对`** ✓，面积比（宿主 ÷ 小框）落在 **1.44 ~ 1.88** ✓，而且**正好分两簇** ✓）：
#:     · **1.44 ~ 1.53（4 对 ✓）** = "**同一块砖被吐了两个框**" ✓ —— 例 `110×80 → 113×113` 比
#:       **1.45**（**用户举的那一对** ✓）、`48×102 → 71×106` 比 1.53 ✓（都是"**半截框 ＋ 整框**"）
#:       ⇒ **该丢小的** ✓；
#:     · **1.88（1 对 ✓）** = 帧 154 的 `97×99 → 152×119` ✓ —— 宿主宽了 55px（**两块砖并排** ✓
#:       而且它自己的面积是当前框表**中位的 2.25 倍** ✓）⇒ **并集框** ⇒ **一块砖都不许丢** ✗。
#:   ⇒ `1.7` 卡在**两簇中间**（两边各留 ~15% ✓）；⚠⚠ 两簇挨得很近 ⇒ **换素材 / 换分辨率后要
#:     **重量一遍** ✓ 别把它当常数背下来 ✗；⚠ 自检里那个并集夹具的比值是 **5.0** ✓（更极端 ✓ 也过 ✓）。
#:   ⚠ 这道门**必须有** ✗✗（**新钉子当场咬住** ✓）：不给 ⇒ 融合期"并集框盖着两块砖"⇒
#:     **每块砖都被当重复丢掉** ⇒ **融合再也分不开** ✗✗（`test_velocity_form_metrics_and_merge`
#:     ⑤ 当场红 ✓）。
_DUP_HOST_K = 1.7


def _dedup(dets, cov=_DUP_COV, host_k=None):
    """**YOLO 重复检出 ⇒ 去重**（用户 2026-10-04 ✓ 见 `_DUP_COV` ✓）。

    用户原话："帧 24 #27 **是凭空生成的**…实际这个检出框**是 #1 的一部分（YOLO 重复检出）**" ✓✓
    ⇒ 这种框**不该建档** ✗（它会让轨迹表凭空多一条 ✓，之后还会混进候选 / 评分 ✓）。
    ⚠ 判据 = **几何 + "所有目标一样大"**（用户的硬先验 ✓）：一个框**几乎整个**落在另一个
      **更大**的框里 ⇒ 它**不可能**是独立目标 ⇒ 只能是"同一处在 YOLO 里吐了两个框"
      （大的 = 合并 / 完整 ✓、小的 = 它的一部分 ✗）✓。
    ⚠ 只跟**更大**的框比 ✓ ⇒ 互相包含那种对称关系不会互相抵消 ✓。

    ⚠⚠ `host_k`（**可选** ✓）= **宿主"跟它大小差不多"的倍数上限**（见 `_DUP_HOST_K` ✓）——
      ⭐⭐⭐⭐⭐ 用户 2026-10-08 ✓ 新增这条**因为实测踩到** ✗✗：**融合期间**那个"并集框"把
      **两块砖**框在同一片里 ✓ ⇒ 每块砖都**整天落在它里面**（覆盖率 ≈ 1.00 ✓）⇒ 不设这道门 ⇒
      **每一块砖都会被当成"重复检出"丢掉** ✗✗ ⇒ **融合再也分不开** ✗（速度跟踪档自检
      `test_velocity_form_metrics_and_merge` ⑤ 当场红 ✓ —— 那就是这条门存在的理由 ✓）。
      · 给了它 ⇒ **比小框大太多（= 并集框）的框不许当宿主** ✓（口径 = `_DUP_HOST_K` ✓ 实测分档
        见它上面那段 ✓ 一处口径 ✓ 别另定一个数 ✗）；
      · **不给**（老底盘那条路 ✓）⇒ **行为一个字不变** ✓（零污染 ✓）。
    ⚠ 返回 `(dups, keep)`：`dups = [(cx, cy, w, h, 宿主cx, 宿主cy, 覆盖率), …]`（**如实报出来** ✓
      演示窗要标它 ✓）；`keep` = 与 `dets` **等长**的布尔表 ✓（`False` = 重复 ⇒ **不配对、不建档、
      也不算进标准面积** ✓）。
    """
    _keep = [True] * len(dets)
    _dups = []
    for _i, _a in enumerate(dets):
        _aa = float(_a[3]) * float(_a[4])
        _host, _best = None, 0.0
        for _j, _b in enumerate(dets):
            if _j == _i or float(_b[3]) * float(_b[4]) <= _aa:
                continue
            if host_k is not None and float(_b[3]) * float(_b[4]) > float(host_k) * _aa:
                continue                       # ⚠ 宿主比它**大得多** ⇒ 那是**并集框**（两块砖）✗
            _c = _cover(_a, _b)
            if _c >= cov and _c > _best:
                _host, _best = _b, _c
        if _host is not None:
            _keep[_i] = False
            _dups.append((float(_a[1]), float(_a[2]), float(_a[3]), float(_a[4]),
                          float(_host[1]), float(_host[2]), float(_best)))
    return _dups, _keep


def _pull_to(_v, _t, _p):
    """**把速度"整体"拉向目标向量**（用户 2026-10-04 ✓ 原话："受框心引导后的圆心相对群体速度 =
    **力度 × (2×框心相对群体速度 − 当前圆心相对群体速度)**" ✓，并按助手建议**目标向量取 EMA** ✓✓）。

    口径（**群体坐标系** ✓）：`v' = v + 力度 × (目标向量 − v)` ✓
      · **力度 = 0** ⇒ **逐位不变** ✓（= 什么都不加 ✓，⚠ 不是"清零" ✗）；
      · **力度 = 1** ⇒ `v' =` **目标向量** ✓（一步到位 ✓）；
      · **力度 > 1** ⇒ **过冲** ✓（拉得越过目标向量 ✓ —— ⚠ 本函数**不做任何夹取** ✗，
        界面「框心力度」的**上界**在建控件那一处（现在是 `3.0` ✓ 用户 2026-10-05 报"**无法调到
        1 以上**" ⇒ 从 `1.0` 放开 ✓ 见 `tools/lie_demo.py` ✓）；⚠⚠ 太大有反效果 ✗：
        目标向量说"这方向不动"时，力度 `2` ⇒ `v' = −v` ✗（**相对速度翻面** ✓）；
      · 目标向量 `_t` = 框心那份 `2×(Δ框心 − 群体中位)` 的 **EMA** ✓（见 `fuse_dir_ema` ✓
        ⇒ **方向与大小都是平滑后的** ✓）。
    ⚠⚠ **与旧 `_add_along` 的两点差别** ✗（= 用户这次要改的 ✓）：
      ① **整体向量** ✓：旧的只改"框心方向"上的**一个分量** ✗ ⇒ 垂直分量**一点不动** ✓；
         新的**连垂直分量一起拉** ✓ ⇒ 垂直分量按 `(1 − 力度)` 收缩 ✓；
      ② 目标方向/大小 = **EMA 平滑** ✓（不是当拍瞬时 ✗ —— 框心位移单拍噪声大、还被 ×2 放大 ✓）。
    ⚠ `_t is None`（这拍没指导 ✓）／`_p <= 0` ⇒ **原样返回** ✓（不猜 ✓）。
    """
    if _t is None or _p <= 0.0:
        return _v
    return (_v[0] + _p * (_t[0] - _v[0]), _v[1] + _p * (_t[1] - _v[1]))


