#: **"贴边"的判据**（框的边离画面边 <= 这么多 px ⇒ 算贴边 ✓）—— ⚠⚠ **用户 2026-10-04 提的**
#:   ✓ 原话："**所有与屏幕边缘不接触、非融合框的应该都可以参与标准大小计算**" ✓✓
#:   ⚠⚠ **实测：这个坑大到离谱** ✗✗ —— `10月1日` 全片 **1146** 个框里，**632 个（55.1%）贴边**
#:     ✓（目标走到画面外被切掉 ✓ 或者干脆是**半个目标** ✓）⇒ 它们的面积**系统性偏小** ✗
#:     ⇒ 拿全框取中位 ⇒ 基准被**拉低 14%**（实测：**19167** vs 过滤后 **22286** ✓ 边长 138 vs 149 ✓）。
#:   ⇒⚠ 后果**不只是"数字不准"** ✗✗：`stuck_ratio = 1.40` 是**除以这个基准** ✓
#:     ⇒ 基准偏小 14% ⇒ 所有框的面积倍数**虚高 14%** ✗ ⇒ **正常框会被误判成"融合"** ✓。
#:   ⚠ 取 2.0 px：容一点抗锯齿与坐标取整 ✓（真正的"切掉"至少切掉几十 px ✓ 分得开 ✓）。
_AREA_EDGE = 2.0
#: **分开之后再缓几拍**（`dev` 仍降权、位置仍偏预测 ✓）。⚠ 为什么非要它 ✗：粘连结束的那一拍
#:   框面积**已经恢复正常**了 ✓ ⇒ 光看"粘连拍"**压不住** ✗ —— 可观测位置还在从"**中点**"
#:   往真位置**跳** ✗（实测帧 15：`dev = 36.5` ✗ 报出的 `pos` 一拍拍出 **39px** ✗）
#:   ⇒ 那一拍照样是"假信号" ✓✗ ⇒ 再缓 2 拍 ✓（实测帧 15 的 `dev` 有效权重从 36.5 降到 ~5.5 ✓）。
_STUCK_COOL = 2
# ---------------- ⭐⭐⭐⭐⭐ **"这一格的观测该信几分"那一档**（用户 2026-10-04 ✓ 他逼出来的 ✓）----
# 用户原话（三句，一句比一句狠 ✓ 全被实测证实 ✓）：
#   ① "**匹配分**是不是代表'这个目标有多像真目标'？" ✓ ⇒ ⚠ **不是** ✗ —— 它是"**这一格的数据
#      能不能信**"（测量质量 ✓）≠ "**它是不是真目标**"（身份判定 ✓ 那是 `dev` / `q` 的活 ✓）。
#      一个**假目标**的框同样可以又干净又准 ⇒ 匹配分照样 1.00 ✓。
#   ② "真假目标**会融合** ⇒ 部分交集时**大概率共用一个检出框**" ✓ ⇒ 实测证实 ✓
#      （帧 35~39 连续 5 拍面积 1.33→1.15x ✓ 帧 64~70 连续 7 拍 ✓）。
#   ③ "融合时期拿**检出框心**当'该往哪走'的指导是**很愚蠢的**" ✓✓ ⇒ **完全对** ✓ 见 `_SUS_NEED` ✓。
#: **"面积可信度"高到可以完全信的线**（≥ 它 ⇒ 权重照旧、**不做任何降权** ✓）——
#:   ⚠⚠ 它比的是 **`ma`（面积因子）**，**不是 `m`（总匹配分）** ✗✗（见 `_Track.ma` ✓）；
#:   ⚠ 取 0.70：面积因子在"正常大小"那档（`_ar ∈ [0.75, 1.0]` ✓）**恒等于 1.0** ✓
#:     ⇒ 好框稳稳在线以上 ⇒ **正常跟踪一个数都不变** ✓✓（硬要求 ✓）。
_M_OK = 0.70
#: **"这一格的面积不可信"的线**（`ma <` 它 ⇒ 记一次可疑 ✓）；连续 `_SUS_NEED` 拍 ⇒ **权重归零** ✓。
_M_SUS = 0.50
#: 连续几拍"不可信" ⇒ 判定为「**持续偏差**」⇒ **位置权重归零 ＋ 停止喂 KF** ✗✗
#:   ⚠⚠⚠ **为什么必须"归零"、而不是"降权"** ✗✗（这一条是本轮最要紧的结论 ✓ 用户第 ③ 句 ✓）：
#:     加权平均的**稳态就是观测本身** ✓ —— 设 `pos ← α·pos + (1−α)·obs`、而 `obs = 真值 + 偏差`，
#:     那么稳态 `pos = obs = 真值 + 偏差` ✗ ⇒ **偏差一寸没少，只是爬得慢** ✗✗。
#:     实测：α = 0.85 ⇒ **5 拍吃掉 56%、7 拍 68%** ✓ 而"粘连连续 5~7 拍"是**常态** ✓
#:     ⇒ **"降权"治不了系统性偏差** ✗ ⇒ 必须**断掉**（权重 0 = 这一拍当"没有观测"✓ 纯滑预测 ✓）。
#:   ⚠ 而"单拍可疑"才用**降权**（`m / _M_OK`）✓ —— 单拍的偏差下一拍就没了 ⇒ 降权够用 ✓。
_SUS_NEED = 2
#: **残缺框**（面积 < 标准面积 × 本值）⇒ 框心是**碎片的重心** ✗ 不能用来定位 ✓。
#:   ⚠ 实测：碎片框的匹配分低（0.16~0.35 ✓）但**方向是随机的**（帧 28 夹角 1°、帧 31 夹角 4°
#:     ✓ —— "恰好在预测正前方"）⇒ **不能用方向判它** ✗（用户提的方向因子我实测过 ✓ 见文档 ✓）。
_SMALL_RATIO = 0.75
# ---------------- ⭐⭐⭐ **跟踪质量自检那一档**（"它还配当目标吗" ✓）-------------------
# 病根（实测 ✓ 上文那条的最后一行 ✓）：粘连把 `#13` 的分数顶高之后，它**帧 16 起 `v_rel ≈ 0.6`**
#   ⇒ **跟着群体一起走** ⇒ 其实**已经跟丢了真目标、改跟一个假目标** ✗ —— 而它**一路"配得上框"、
#   从不换目标** ⇒ 界面上**看起来完全正常** ✗✗（这类错误**最难发现** ✓）。
# ⇒ 判据：**"不合群"是它的唯一立身之本** ✓ ⇒ 那就**一直盯着它到底还合不合群** ——
#   `q = |v_rel| 的滑动中位 ÷ 噪声底` ⇒ 持续低于阈值 ⇒ **它已经不再是那个人了** ⇒ 降权、放开换 ✓。
#: 滑动窗口（拍）：太短会被单拍抖动带跑 ✗ 太长反应慢 ✗（10 拍 ≈ 1 秒 ✓）。
_Q_WIN = 10
#: **比值下限**：`q` 低于它 ⇒ 算"这一拍它没在合群" ✓。⚠ 按噪声底归一 ⇒ 换素材不用改它 ✓。
_Q_MIN = 1.5
#: **窗口（`_Q_WIN` 拍）里有多少拍"没在合群"⇒ 判"跟丢了"** ✓（⚠ **用"占比"、不用"连续"** ✗✗）。
#:   ⚠⚠ 这是**踩过坑改的**（实测 ✓）：原来写"**连续** N 拍 < 阈值" ✗ ⇒ 而 `q` 一直在阈值附近
#:   **晃**（实测 0.41 → 0.55 → 1.75 ✓）⇒ 一过线就**清零** ⇒ 计数**最多只到 1** ✗ ⇒
#:   **这条自检等于没开** ✓（目标明明跟丢了，日志却什么都不说 ✓）。
#:   ⇒ 改成"**最近 10 拍里有 6 拍不合群**" ⇒ 晃几下**不影响** ✓✓。
#:   （⚠ 要窗口**填满**才判 ⇒ 换目标后的头 10 拍不会被误伤 ✓ 见 `process` ⑧ ✓）
_Q_NEED = 6
#: 判定"跟丢"之后，目标轨迹分数**每拍额外乘**它（⇒ 让真候选有机会超过它 ✓；不直接清空 ⇒
#:   万一只是目标"暂时静止"，回来还能接着用 ✓）。
_Q_DECAY = 0.60
# ---------------- 白度辅助（`pick_white` 那一套 ✓ 保留 ✓ 见模块头 ⚠）----------------
_WHITE_Q = 95.0
#: ⭐⭐⭐⭐⭐ **白块面积下限**（用户 2026-10-05 ✓ 原话："**为什么找到了 明显属于假目标的检出框**"
#:   ✓✓ ⇒ 修法「1」✓）：**300 → 2000**（≈ 画面 0.5% ✓）。
#:   ⚠⚠ **实测依据**（`10月3日 (2).mp4` ✓ 逐拍量 `pick_white` 的**面积**）：
