#:     · **假白块**（帧 19 / 22 / 44 / 47 ✓ 各处乱闪）：**307 / 343 / 353 / 360**（0.08~0.10% ✗）
#:       ⇒ 全是**画面里的小亮斑**（记分牌/反光之类 ✓），**差 25 倍** ⇒ 300 这道门根本挡不住 ✗✗。
